/* ------------------------------------------------------------------ */
/*  Color variables — sampled directly from Elan Creative Studio's     */
/*  Figma palette swatches (tint / base / shade / dark per hue).       */
/*  `base` is the true brand color, used for swatches, borders, and    */
/*  fills. `label` is one step darker where needed so white text on    */
/*  a solid label background stays legible (red and purple are        */
/*  already dark enough at `base`; gold needs to drop two steps).      */
/* ------------------------------------------------------------------ */
const PALETTE = {
  red: { tint: "#FF9885", base: "#E63917", shade: "#B32B11", dark: "#81200D" },
  gold: { tint: "#FFD978", base: "#FFC42C", shade: "#D99726", dark: "#704F00" },
  green: { tint: "#62D989", base: "#2DB35A", shade: "#238C47", dark: "#196632" },
  teal: { tint: "#6CD3F2", base: "#1397BE", shade: "#1183A7", dark: "#0A5A73" },
  purple: { tint: "#BAADFC", base: "#7055F2", shade: "#5E47CB", dark: "#4D3AA6" },
};

// `labelBg` is the hue washed almost all the way into white; `labelText` is
// the lightest step of the same hue that still reads at label size on it —
// shade for red and purple, dark for green and teal, which are lighter hues.
const TAGS = {
  "logo-design": { label: "Logo Design", color: PALETTE.red.base, labelColor: PALETTE.red.base, tint: PALETTE.red.tint, labelBg: "#FCEBE8", labelText: PALETTE.red.shade },
  "visual-identity": { label: "Visual Identity", color: PALETTE.green.base, labelColor: PALETTE.green.base, tint: PALETTE.green.tint, labelBg: "#EAF7EE", labelText: PALETTE.green.dark },
  "print-design": { label: "Print Design", color: PALETTE.purple.base, labelColor: PALETTE.purple.base, tint: PALETTE.purple.tint, labelBg: "#F1EEFE", labelText: PALETTE.purple.shade },
  "user-interface": { label: "User Interface", color: PALETTE.teal.base, labelColor: PALETTE.teal.base, tint: PALETTE.teal.tint, labelBg: "#E7F5F8", labelText: PALETTE.teal.dark },
  "digital-design": { label: "Digital Design", color: PALETTE.gold.base, labelColor: PALETTE.gold.base, tint: PALETTE.gold.tint, labelBg: "#FFF6E0", labelText: PALETTE.gold.dark },
};

