// Word-by-word scroll reveal for the section headlines home.css scopes it to
// (.scroll-reveal / .scroll-reveal__word / .is-visible). Each word starts
// blurred/faded/offset and transitions to sharp/opaque/in-place (staggered
// via transitionDelay) the moment the *container's own position* reaches the
// center of the viewport — a single trigger, not a scroll-scrubbed step
// animation. By default that trigger fires once and the listener detaches
// for good (Services/Process's headlines: reveal once, stay revealed).
// Pass `repeat` for text that should instead reset back to hidden and
// re-trigger the next time it's scrolled back to center — but only when
// scrolled back *below* the viewport (rect.top >= vh, i.e. you scrolled up
// past where it used to be). Scrolling forward past it — it now sits above
// the viewport — leaves it revealed: come back to it later without having
// gone all the way back below it first, and it's still in its finished
// state, not replaying.
function ScrollRevealText({ text, className, repeat = false }) {
  const rootRef = useRef(null);
  const revealedRef = useRef(false);
  const words = useMemo(() => text.split(" "), [text]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root || typeof window === "undefined") return;

    const setVisible = (visible) => {
      root.querySelectorAll(".scroll-reveal__word").forEach((el) => el.classList.toggle("is-visible", visible));
    };

    let frame = null;
    const measure = () => {
      frame = null;
      const rect = root.getBoundingClientRect();
      const vh = window.innerHeight;
      const inView = rect.bottom > 0 && rect.top < vh;
      const belowViewport = rect.top >= vh;
      // Trigger point: the headline's own vertical center reaching 20% up
      // from the bottom of the viewport — i.e. 80% down from the top, the
      // more natural direction getBoundingClientRect() measures in.
      const center = rect.top + rect.height / 2;

      if (repeat && revealedRef.current && belowViewport) {
        revealedRef.current = false;
        setVisible(false);
      }

      if (!revealedRef.current && inView && center <= vh * 0.8) {
        revealedRef.current = true;
        setVisible(true);
        if (!repeat) {
          cleanup();
        }
      }
    };

    const onScroll = () => {
      if (frame === null) frame = requestAnimationFrame(measure);
    };
    function cleanup() {
      if (frame !== null) cancelAnimationFrame(frame);
      document.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onScroll);
    }

    measure(); // covers text already past center on mount
    document.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onScroll);
    return cleanup;
  }, [words, repeat]);

  return (
    <span ref={rootRef} className={`scroll-reveal ${className || ""}`}>
      {words.map((word, i) =>
        // A standalone "\n" token (surrounded by spaces in `text`, e.g.
        // "studio, \n for") forces a line break instead of animating in as
        // a word — matches a Figma <br> between two lines of a headline.
        word === "\n" ? (
          <br key={i} aria-hidden />
        ) : (
          <React.Fragment key={i}>
            <span className="scroll-reveal__word" style={{ transitionDelay: `${i * 0.02}s` }}>
              {word}
            </span>
            {/* A separate, un-tracked span — not appended inside the word's
                own inline-block above. A word's negative letter-spacing
                (inherited from whatever headline this sits in, e.g.
                --fs-900-tracking on the hero) applies to every character in
                its box, the trailing space included, which at a large
                enough negative value shrinks that space to nearly nothing;
                isolating it here with tracking reset keeps inter-word
                spacing normal regardless of how tight a given headline's
                own tracking is. */}
            {i < words.length - 1 && words[i + 1] !== "\n" && <span style={{ letterSpacing: "normal" }}> </span>}
          </React.Fragment>
        )
      )}
    </span>
  );
}

// Same word-by-word blur/fade/lift as ScrollRevealText (reuses its exact
// .scroll-reveal/.scroll-reveal__word/.is-visible classes and stagger), but
// triggered by mounting rather than by scroll position — for text that's
// meant to play the moment it's allowed to appear (e.g. the hero headline,
// gated on the loading screen finishing) regardless of where on the page
// that happens to sit, rather than needing to already satisfy
// ScrollRevealText's "is this actually in view" check at that instant.
function AutoRevealText({ text, className, delay = 0 }) {
  const [visible, setVisible] = useState(false);
  const words = useMemo(() => text.split(" "), [text]);

  useEffect(() => {
    if (delay > 0) {
      const timer = setTimeout(() => setVisible(true), delay);
      return () => clearTimeout(timer);
    }
    const raf = requestAnimationFrame(() => setVisible(true));
    return () => cancelAnimationFrame(raf);
  }, [delay]);

  return (
    <span className={`scroll-reveal ${className || ""}`}>
      {words.map((word, i) =>
        word === "\n" ? (
          <br key={i} aria-hidden />
        ) : (
          <React.Fragment key={i}>
            <span
              className={`scroll-reveal__word${visible ? " is-visible" : ""}`}
              style={{ transitionDelay: `${i * 0.02}s` }}
            >
              {word}
            </span>
            {/* A separate, un-tracked span — not appended inside the word's
                own inline-block above. A word's negative letter-spacing
                (inherited from whatever headline this sits in, e.g.
                --fs-900-tracking on the hero) applies to every character in
                its box, the trailing space included, which at a large
                enough negative value shrinks that space to nearly nothing;
                isolating it here with tracking reset keeps inter-word
                spacing normal regardless of how tight a given headline's
                own tracking is. */}
            {i < words.length - 1 && words[i + 1] !== "\n" && <span style={{ letterSpacing: "normal" }}> </span>}
          </React.Fragment>
        )
      )}
    </span>
  );
}

// "Effect 4" from scroll-type.webflow.io (a GSAP+ScrollTrigger reference
// site for scroll-scrubbed text) — reimplemented on this codebase's own
// continuous rAF/LERP convention instead of pulling in GSAP: every
// character starts invisible, tipped back -90° around its own top edge
// (transform-origin: 50% 0%, matching the reference) and pushed back
// -200px in 3D depth, then flips upright to flat/opaque/at-rest as the
// text's own position crosses a scroll window — continuously scrubbed and
// reversible (not a one-shot trigger the way ScrollRevealText/
// AutoRevealText's word reveal is), each character consuming its own
// slice of that single 0-1 progress so they settle staggered rather than
// in unison (the reference does this with GSAP's stagger option on a
// scrubbed tween; same idea, done by hand here). TRIAL — only wired up on
// one headline for now, see its call site.
function CharFlipRevealText({ text, className, accentWords = [] }) {
  const rootRef = useRef(null);
  const charRefs = useRef([]);
  charRefs.current = [];
  let charIndex = 0;

  const words = useMemo(() => text.split(" "), [text]);
  // Same accent-range approach as CharFlipAutoChars — [start, end) ranges
  // against the original text (spaces included) so a multi-word phrase
  // still colors correctly across the space between its words.
  const accentRanges = useMemo(
    () =>
      accentWords
        .map((phrase) => {
          const start = text.indexOf(phrase);
          return start === -1 ? null : [start, start + phrase.length];
        })
        .filter(Boolean),
    [text, accentWords]
  );
  const isAccentAt = (pos) => accentRanges.some(([start, end]) => pos >= start && pos < end);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    // See Services' ladder/scale effect for why coarse pointers skip LERP
    // (and, below, the perpetual rAF loop itself) too.
    const isTouch = window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
    const skipLerp = reduce || isTouch;

    // Trigger window, in "% down from the top" (this file's usual
    // convention) — starts as the text's own top nears the very bottom of
    // the viewport, finishes well before it reaches center, roughly
    // matching the reference's "center bottom" → "bottom top+=20%" window
    // without needing this codebase's simpler fixed-percentage math to
    // also depend on the text's own measured height.
    const START_PCT = 0.95;
    const END_PCT = 0.35;
    // How much of the shared 0-1 progress the stagger itself eats up —
    // the rest (1 - this) is each character's own individual flip/fade,
    // once its turn arrives.
    const STAGGER_FRACTION = 0.6;
    const LERP = 0.22;
    const smoothstep = (t) => t * t * (3 - 2 * t);

    const total = charRefs.current.length;
    const current = new Array(total).fill(0);
    let frame = null;
    // Cached, not read fresh in measure() — see Services' ladder/scale
    // effect for why: window.innerHeight changes live as a mobile browser's
    // address bar shows/hides, which would otherwise jump this animation's
    // computed progress exactly when that happens mid-scroll.
    let vh = window.innerHeight;
    let lastWidth = window.innerWidth;

    const measure = () => {
      frame = null;
      const root = rootRef.current;
      if (root && total > 0) {
        const rect = root.getBoundingClientRect();
        const startY = vh * START_PCT;
        const endY = vh * END_PCT;
        const progress = Math.min(1, Math.max(0, (startY - rect.top) / (startY - endY)));

        charRefs.current.forEach((el, i) => {
          if (!el) return;
          const charStart = (i / total) * STAGGER_FRACTION;
          const span = 1 - STAGGER_FRACTION;
          const charProgress = span > 0 ? Math.min(1, Math.max(0, (progress - charStart) / span)) : progress;
          const target = smoothstep(charProgress);
          current[i] = skipLerp ? target : current[i] + (target - current[i]) * LERP;
          el.style.opacity = current[i].toFixed(3);
          el.style.transform = `rotateX(${(-CHAR_FLIP_ROTATE_DEG * (1 - current[i])).toFixed(2)}deg) translateZ(${(-CHAR_FLIP_DEPTH_PX * (1 - current[i])).toFixed(1)}px)`;
        });
      }
    };

    // See Services' ladder/scale effect (same file) for the full reasoning:
    // once LERP is skipped there's no easing tail to fill in between scroll
    // events, so this goes event-driven instead of an unconditional
    // self-rescheduling rAF loop — that loop running forever regardless of
    // scroll activity is what actually competes with the browser's own
    // scroll thread on mobile.
    if (skipLerp) {
      measure();
      const onScroll = () => {
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      const onResize = () => {
        if (window.innerWidth !== lastWidth) {
          lastWidth = window.innerWidth;
          vh = window.innerHeight;
        }
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      document.addEventListener("scroll", onScroll, true);
      window.addEventListener("resize", onResize);
      return () => {
        if (frame !== null) cancelAnimationFrame(frame);
        document.removeEventListener("scroll", onScroll, true);
        window.removeEventListener("resize", onResize);
      };
    }

    const onResizeDesktop = () => {
      if (window.innerWidth !== lastWidth) {
        lastWidth = window.innerWidth;
        vh = window.innerHeight;
      }
    };
    const tick = () => {
      measure();
      frame = requestAnimationFrame(tick);
    };
    window.addEventListener("resize", onResizeDesktop);
    frame = requestAnimationFrame(tick);
    return () => {
      if (frame !== null) cancelAnimationFrame(frame);
      window.removeEventListener("resize", onResizeDesktop);
    };
  }, [words]);

  let pos = 0; // walks the original text in lockstep with `words`, spaces included
  return (
    <span ref={rootRef} className={`char-flip ${className || ""}`}>
      {words.map((word, wi) => {
        if (word === "\n") {
          pos += 1;
          return <br key={wi} aria-hidden />;
        }
        const wordStart = pos;
        pos += word.length + 1; // +1 for the space split() consumed between words
        return (
          <React.Fragment key={wi}>
            <span className="char-flip__word">
              {[...word].map((ch, ci) => {
                const idx = charIndex++;
                const accent = isAccentAt(wordStart + ci);
                return (
                  <span
                    key={ci}
                    ref={(el) => (charRefs.current[idx] = el)}
                    className={`char-flip__char${accent ? " char-flip__char--accent" : ""}`}
                  >
                    {ch}
                  </span>
                );
              })}
            </span>
            {wi < words.length - 1 && words[wi + 1] !== "\n" && <span style={{ letterSpacing: "normal" }}> </span>}
          </React.Fragment>
        );
      })}
    </span>
  );
}

// Matches CharFlipAutoChars' own default staggerStep (.02s) and
// .char-flip-auto__char's CSS transition-duration (.6s) — named constants,
// not just inline numbers, so charFlipRevealMs (below) can compute exactly
// when a given headline's own reveal actually finishes, for sequencing
// other things off of it (the hero's line-separator, for one) instead of
// guessing/hardcoding a delay by eye.
const CHAR_FLIP_STAGGER_MS = 20;
const CHAR_FLIP_DURATION_MS = 600;
// Shared "how far tipped back" starting pose for BOTH flip variants —
// CharFlipRevealText's continuously scroll-scrubbed one (consumed directly
// below, in its own per-frame transform string) and CharFlipAutoChars' CSS-
// transitioned one (piped into home.css's .char-flip-auto__char via a
// --char-flip-rotate/--char-flip-depth custom property, set inline where
// that markup renders below — see AutoCharFlipRevealText/
// ScrollCharFlipRevealText). One pair of numbers, so tuning the flip's
// depth/angle can't require remembering to update it in two places/two
// languages that would otherwise silently drift apart.
const CHAR_FLIP_ROTATE_DEG = 45;
const CHAR_FLIP_DEPTH_PX = 16;

// How long, in ms, `text` takes to fully reveal via CharFlipAutoChars once
// its own `visible` flips true — every real character (not "\n" line-break
// tokens or the untracked inter-word spaces) gets staggerStep more
// transition-delay than the last, so the last one to *start* is the
// (n-1)th; it then takes its own full transition-duration to finish.
function charFlipRevealMs(text) {
  const charCount = text
    .split(" ")
    .filter((word) => word !== "\n")
    .reduce((sum, word) => sum + [...word].length, 0);
  return (charCount - 1) * CHAR_FLIP_STAGGER_MS + CHAR_FLIP_DURATION_MS;
}

// Time-driven variant of "effect 4" (see CharFlipRevealText above) — CSS-
// transitioned per character instead of continuously scroll-scrubbed: each
// character transitions exactly once, staggered by transitionDelay, the
// moment `visible` flips true, then keeps playing on its own regardless of
// further scrolling — the same mechanism AutoRevealText/ScrollRevealText
// already use for their word-by-word reveal (mount+delay vs. viewport-
// center trigger), just applied per character here with effect 4's flip/
// depth properties instead of blur/lift. Shared render between the two
// trigger variants below; only what flips `visible` differs.
function CharFlipAutoChars({ text, visible, staggerStep = CHAR_FLIP_STAGGER_MS / 1000, accentWords = [] }) {
  const words = useMemo(() => text.split(" "), [text]);
  // [start, end) character ranges within the ORIGINAL text (spaces
  // included), one per accentWords entry — computed against the full
  // string rather than per-word so a multi-word phrase like "visual
  // identity" still colors correctly across the space between its words.
  const accentRanges = useMemo(
    () =>
      accentWords
        .map((phrase) => {
          const start = text.indexOf(phrase);
          return start === -1 ? null : [start, start + phrase.length];
        })
        .filter(Boolean),
    [text, accentWords]
  );
  const isAccentAt = (pos) => accentRanges.some(([start, end]) => pos >= start && pos < end);

  let charIndex = 0;
  let pos = 0; // walks the original text in lockstep with `words`, spaces included
  return words.map((word, wi) => {
    if (word === "\n") {
      pos += 1;
      return <br key={wi} aria-hidden />;
    }
    const wordStart = pos;
    pos += word.length + 1; // +1 for the space split() consumed between words
    return (
      <React.Fragment key={wi}>
        <span className="char-flip-auto__word">
          {[...word].map((ch, ci) => {
            const idx = charIndex++;
            const accent = isAccentAt(wordStart + ci);
            return (
              <span
                key={ci}
                className={`char-flip-auto__char${visible ? " is-visible" : ""}${accent ? " char-flip-auto__char--accent" : ""}`}
                style={{ transitionDelay: `${(idx * staggerStep).toFixed(2)}s` }}
              >
                {ch}
              </span>
            );
          })}
        </span>
        {wi < words.length - 1 && words[wi + 1] !== "\n" && <span style={{ letterSpacing: "normal" }}> </span>}
      </React.Fragment>
    );
  });
}

// Hero's own two headline lines use this — plays the moment it's allowed to
// (heroReady, then an optional extra `delay`), full stop, same reasoning as
// AutoRevealText: right at the top of the page, so it shouldn't also have
// to satisfy a scroll-position check.
function AutoCharFlipRevealText({ text, className, delay = 0, accentWords }) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (delay > 0) {
      const timer = setTimeout(() => setVisible(true), delay);
      return () => clearTimeout(timer);
    }
    const raf = requestAnimationFrame(() => setVisible(true));
    return () => cancelAnimationFrame(raf);
  }, [delay]);

  return (
    <span
      className={`char-flip-auto ${className || ""}`}
      style={{ "--char-flip-rotate": `${CHAR_FLIP_ROTATE_DEG}deg`, "--char-flip-depth": `${CHAR_FLIP_DEPTH_PX}px` }}
    >
      <CharFlipAutoChars text={text} visible={visible} accentWords={accentWords} />
    </span>
  );
}

// Process's headline uses this — same trigger point as ScrollRevealText
// (the headline's own center reaching 80% down the viewport, i.e. 20% from
// the bottom). By default fires once and detaches for good; pass `repeat`
// for it to instead reset back to hidden and re-trigger the next time it's
// scrolled back to center — same convention (and same reset condition:
// only once scrolled back *below* the viewport) as ScrollRevealText's own
// `repeat` prop.
function ScrollCharFlipRevealText({ text, className, repeat = false }) {
  const rootRef = useRef(null);
  const revealedRef = useRef(false);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const root = rootRef.current;
    if (!root || typeof window === "undefined") return;

    let frame = null;
    const measure = () => {
      frame = null;
      const rect = root.getBoundingClientRect();
      const vh = window.innerHeight;
      const inView = rect.bottom > 0 && rect.top < vh;
      const belowViewport = rect.top >= vh;
      const center = rect.top + rect.height / 2;

      if (repeat && revealedRef.current && belowViewport) {
        revealedRef.current = false;
        setVisible(false);
      }

      if (!revealedRef.current && inView && center <= vh * 0.8) {
        revealedRef.current = true;
        setVisible(true);
        if (!repeat) {
          cleanup();
        }
      }
    };
    const onScroll = () => {
      if (frame === null) frame = requestAnimationFrame(measure);
    };
    function cleanup() {
      if (frame !== null) cancelAnimationFrame(frame);
      document.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onScroll);
    }

    measure(); // covers text already past center on mount
    document.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onScroll);
    return cleanup;
  }, [repeat]);

  return (
    <span
      ref={rootRef}
      className={`char-flip-auto ${className || ""}`}
      style={{ "--char-flip-rotate": `${CHAR_FLIP_ROTATE_DEG}deg`, "--char-flip-depth": `${CHAR_FLIP_DEPTH_PX}px` }}
    >
      <CharFlipAutoChars text={text} visible={visible} />
    </span>
  );
}

// Shared by Services (node 721:1990) and Process (node 676:1513) — both use
// the identical card shape: a filled color tab strip up top (a category
// label, optionally a second one alongside it — Process's week/phase tag)
// and a title + body-copy block below (.card-tab/.card-tab__body in
// home.css). Each section's own scroll animation drives completely
// different CSS on the *outer* box though — Process's absolute
// entrance-stack transform vs Services' laddered parallax transform — so
// that part stays each caller's own `className` + `cardRef`, not shared
// here.
// `tone` overrides both the title's and body's text-color tone together
// (e.g. Process's now-light k-0 card needs tone-dark; Services' still-dark
// k-900 card keeps the defaults below unset).
function TabCard({ cardRef, className, tabColor, tab, secondaryTab, title, body, glow, titleTone = "light", bodyTone = "muted" }) {
  return (
    <div ref={cardRef} className={className}>
      {glow}
      <div className={`card-tab card-tab--${tabColor}`}>
        <p>{tab}</p>
        {secondaryTab && <p>{secondaryTab}</p>}
      </div>
      <div className="card-tab__body">
        <h3 className={`card-title tone-${titleTone}`}>{title}</h3>
        <p className={`body-text card-tab__text tone-${bodyTone}`}>{body}</p>
      </div>
    </div>
  );
}

function Services() {
  const gridRef = useRef(null);
  const cardRefs = useRef([]);
  const headerRef = useRef(null);

  // Ladder-height parallax: each card animates from a shared 420px starting
  // offset to its own staggered end value — 2×/1×/0× --sp-600, the ladder's
  // original values — then holds there, while also scaling from .6 to 1
  // over that same progress/interval (its own LERPed value, same as the
  // translateY one, just a separate target). Driven by the *grid's* own
  // position, not each card's: measuring a card's own position would feed
  // back on itself, since its offset moves its own top edge. Continuous
  // function of scroll, so it reverses smoothly scrolling back down too.
  // Only applies at the Laptop breakpoint and up (900px), where this
  // ladder layout exists; below that the cards sit in the diagonal
  // stairstep grid instead.
  //
  // Written as transform:translateY()/scale(), not margin-top: margin is a layout
  // property, so writing it one frame and then reading
  // grid.getBoundingClientRect() the next forces the browser to resolve the
  // whole page's layout before it can answer — a synchronous reflow, every
  // frame, for as long as anything on the page is scrolling. That's what
  // was actually dragging the whole hero down, not the animation logic
  // itself. transform doesn't invalidate layout, so the read that follows
  // it stays cheap. (.services__grid reserves the room the transformed
  // cards need via padding-bottom instead, in home.css — a static value,
  // not written every frame, so it doesn't reintroduce the problem.)
  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    // LERP below exists to fill the gaps between discrete desktop wheel/
    // trackpad scroll events (see its own comment) — touch scrolling has no
    // such gaps (the compositor delivers a continuous stream), so easing
    // toward a moving target here just adds a trailing settle *after* the
    // finger lifts and the page has already stopped, which reads as a stray
    // lag/jump on mobile. Snapping straight to target on coarse pointers
    // (same treatment as prefers-reduced-motion) removes that tail without
    // touching the desktop smoothing it's actually there for.
    const isTouch = window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
    const skipLerp = reduce || isTouch;

    const START = 420; // px, shared starting offset for all three cards
    const MULTIPLIER = [2, 1, 0]; // × --sp-600, each card's end value (matches the ladder's original CSS)
    // Scale has its own trigger window, separate from the ladder's below,
    // and it's read from each card's own real, current top edge — not an
    // approximation derived from the grid or the ladder's offset (both
    // tried, neither actually matched "each card's own top" once the
    // ladder had visibly staggered them). .6 the moment a card's own top
    // reaches the very bottom of the viewport (0% from bottom), 1 once
    // that same edge has scrolled up to 20% from the bottom (80% down from
    // the top — see SCALE_START_PCT/SCALE_END_PCT below for the same
    // top-down conversion the ladder's START_PCT/END_PCT use). Reading a
    // card's own getBoundingClientRect() here is safe even though the
    // ladder's translateY is also live on the same element: current[i]
    // (what drives translateY) is computed from the grid's position only,
    // never read back from the card, so there's no loop on that axis —
    // scale reads translateY's *result*, not the other way around. scale's
    // own contribution to that same rect (transform-origin:center shifting
    // the visual top slightly as it shrinks) does feed back into itself a
    // little, but it's LERPed and bounded to a small, fixed range (scale
    // never goes below .6), so it settles rather than runs away.
    const START_SCALE = 0.6;
    const END_SCALE = 1;
    const SCALE_START_PCT = 1;
    const SCALE_END_PCT = 0.8;
    // Ladder's own trigger window, in "% from the bottom of the viewport"
    // (as given) — converted to the more natural top-down % a
    // getBoundingClientRect().top is measured in: 10%/70% from the bottom =
    // 90%/30% down from the top, and vice versa. Animation starts once the
    // grid's top has scrolled up to 10% from the bottom, ends (and holds)
    // once it reaches 70% from the bottom.
    const START_PCT = 0.9;
    const END_PCT = 0.3;
    // LERP is why this is a continuous rAF loop rather than a scroll-event
    // listener: a scroll (or wheel/trackpad) event fires in discrete jumps,
    // not a smooth stream, so driving the offset directly off it visibly
    // steps between those jumps. Running every frame regardless of whether
    // a scroll event just fired, and easing the *displayed* value toward
    // the live target by this fraction each frame, fills in the gaps —
    // same technique the old useScrollDeform hook used for its skew.
    const LERP = 0.22;
    const current = MULTIPLIER.map(() => START);
    const currentScale = MULTIPLIER.map(() => START_SCALE);
    let frame = null;

    // --sp-600 only changes at breakpoints, not every frame — read it once
    // and on resize instead of calling getComputedStyle() (a style-recalc,
    // not free) on every single animation frame indefinitely.
    let sp600 = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--sp-600")) || 0;
    // Cached the same way — window.innerHeight shrinks/grows live as a
    // mobile browser's address bar shows/hides while scrolling, and this
    // effect recomputes on every scroll event once skipLerp is active, so
    // reading it fresh here let a toolbar transition jump this card's
    // computed position mid-gesture (or right as it settles) even after
    // the LERP-tail and perpetual-rAF-loop fixes — this was the actual
    // remaining cause of the reported lag specifically around the address
    // bar showing/hiding. Only refreshed on a real resize (width actually
    // changed), never on the height-only change a toolbar produces.
    let vh = window.innerHeight;
    let lastWidth = window.innerWidth;
    const refreshSp600 = () => {
      sp600 = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--sp-600")) || 0;
      if (window.innerWidth !== lastWidth) {
        lastWidth = window.innerWidth;
        vh = window.innerHeight;
      }
    };

    const measure = () => {
      frame = null;
      const grid = gridRef.current;
      if (grid) {
        // Scale runs at every width — its own window (0% to 20% from the
        // bottom) doesn't depend on the ladder being active. The ladder
        // (translateY) below it only applies at 900px+, where the flex-row
        // layout it's built for actually exists (must match .services__grid's
        // own 900px breakpoint in home.css, not drift from it).
        const isLadder = window.innerWidth >= 900;
        const top = grid.getBoundingClientRect().top;
        const scaleStartY = vh * SCALE_START_PCT;
        const scaleEndY = vh * SCALE_END_PCT;

        // Only computed/used when isLadder — see below.
        let progress = 0;
        if (isLadder) {
          const startY = vh * START_PCT;
          const endY = vh * END_PCT;
          progress = Math.min(1, Math.max(0, (startY - top) / (startY - endY)));
        }

        cardRefs.current.forEach((el, i) => {
          if (!el) return;
          // Below 900px current[i] just holds at its resting START value
          // (untouched, no LERP) so that growing the window back past 900px
          // resumes the ladder from the same place it would've been at,
          // rather than snapping in from 0 — but it's left out of the
          // rendered transform entirely while !isLadder, so no translateY
          // actually shows on smaller screens.
          if (isLadder) {
            const target = START + (MULTIPLIER[i] * sp600 - START) * progress;
            current[i] = skipLerp ? target : current[i] + (target - current[i]) * LERP;
          }
          // This card's own real, current top edge — not the grid's, not
          // an approximation of it. Read *after* current[i] was updated
          // above but *before* this frame's transform is written below, so
          // it reflects last frame's rendered position (one frame behind
          // live, same as any other read-before-write in a rAF loop).
          const cardRectTop = el.getBoundingClientRect().top;
          const cardScaleProgress = Math.min(1, Math.max(0, (scaleStartY - cardRectTop) / (scaleStartY - scaleEndY)));
          const targetScale = START_SCALE + (END_SCALE - START_SCALE) * cardScaleProgress;
          currentScale[i] = skipLerp ? targetScale : currentScale[i] + (targetScale - currentScale[i]) * LERP;
          el.style.transform = isLadder
            ? `translateY(${current[i].toFixed(2)}px) scale(${currentScale[i].toFixed(4)})`
            : `scale(${currentScale[i].toFixed(4)})`;
        });
      }
    };

    // skipLerp (touch, or prefers-reduced-motion) means every value above
    // already snaps straight to its target — nothing is left to ease in
    // between scroll events, so there's no reason to keep a rAF callback
    // queued 60×/sec for as long as Home stays mounted, scrolling or not.
    // That unconditional self-reschedule (still used below for desktop,
    // where the LERP genuinely needs a per-frame ticker to fill the gaps
    // between discrete wheel/trackpad events) was real, constant main-
    // thread work — competing with the browser's own scroll/compositing
    // thread for exactly the frames right as a scroll gesture ends, which
    // is what actually produced the lag/jump on mobile, independent of
    // whether LERP itself was skipped. Event-driven — one measure per
    // actual scroll/resize — matches WorkSection/ProcessStack's own
    // pattern and removes that ambient cost entirely on mobile.
    if (skipLerp) {
      measure();
      const onScroll = () => {
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      const onResize = () => {
        refreshSp600();
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      document.addEventListener("scroll", onScroll, true);
      window.addEventListener("resize", onResize);
      return () => {
        if (frame !== null) cancelAnimationFrame(frame);
        document.removeEventListener("scroll", onScroll, true);
        window.removeEventListener("resize", onResize);
      };
    }

    const tick = () => {
      measure();
      frame = requestAnimationFrame(tick);
    };
    window.addEventListener("resize", refreshSp600);
    frame = requestAnimationFrame(tick);
    return () => {
      if (frame !== null) cancelAnimationFrame(frame);
      window.removeEventListener("resize", refreshSp600);
    };
  }, []);

  // .services__header parallax: translateY -160px→+160px as the header's
  // own top edge scrolls from 70% down the viewport to 20% down it — a
  // continuous function of scroll position (not a one-shot trigger), so it
  // reverses smoothly scrolling back up too. Its own effect/rAF loop, not
  // folded into the ladder's above: independent element, independent
  // trigger window, no reason to couple them.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    // See the ladder/scale effect above for why coarse pointers skip LERP
    // too — same trailing-settle-after-scroll-stops issue on mobile.
    const isTouch = window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
    const skipLerp = reduce || isTouch;

    const START_Y = -240;
    const END_Y = 0;
    const START_PCT = 0.7; // % down from the top of the viewport
    const END_PCT = 0.2;
    const LERP = 0.22;
    let current = START_Y;
    let frame = null;
    // Cached, not read fresh in measure() — see the ladder/scale effect
    // above for why: window.innerHeight changes live as a mobile browser's
    // address bar shows/hides, which would otherwise jump this element's
    // computed position exactly when that happens mid-scroll.
    let vh = window.innerHeight;
    let lastWidth = window.innerWidth;

    const measure = () => {
      frame = null;
      const header = headerRef.current;
      if (header) {
        const top = header.getBoundingClientRect().top;
        const startY = vh * START_PCT;
        const endY = vh * END_PCT;
        const progress = Math.min(1, Math.max(0, (startY - top) / (startY - endY)));
        const target = START_Y + (END_Y - START_Y) * progress;
        current = skipLerp ? target : current + (target - current) * LERP;
        header.style.transform = `translateY(${current.toFixed(2)}px)`;
      }
    };

    // See the ladder/scale effect above for why this goes event-driven
    // instead of an unconditional self-rescheduling loop once LERP is
    // skipped — the perpetual rAF polling itself (not just the easing) is
    // what was competing with the browser's own scroll thread on mobile.
    if (skipLerp) {
      measure();
      const onScroll = () => {
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      const onResize = () => {
        if (window.innerWidth !== lastWidth) {
          lastWidth = window.innerWidth;
          vh = window.innerHeight;
        }
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      document.addEventListener("scroll", onScroll, true);
      window.addEventListener("resize", onResize);
      return () => {
        if (frame !== null) cancelAnimationFrame(frame);
        document.removeEventListener("scroll", onScroll, true);
        window.removeEventListener("resize", onResize);
      };
    }

    // Desktop has no dynamic toolbar, but this still only refreshes vh on
    // an actual resize (matching the touch path above) rather than baking
    // in a one-time value at mount, so a real window resize still works.
    const onResizeDesktop = () => {
      if (window.innerWidth !== lastWidth) {
        lastWidth = window.innerWidth;
        vh = window.innerHeight;
      }
    };
    const tick = () => {
      measure();
      frame = requestAnimationFrame(tick);
    };
    window.addEventListener("resize", onResizeDesktop);
    frame = requestAnimationFrame(tick);
    return () => {
      if (frame !== null) cancelAnimationFrame(frame);
      window.removeEventListener("resize", onResizeDesktop);
    };
  }, []);

  return (
    <section className="services">
      <div className="services__inner">
        <div ref={headerRef} className="services__header">
          <h2 className="section-headline tone-muted services__headline">
            <CharFlipRevealText
              text={"Full scope of services to build memorable brand"}
              accentWords={["memorable"]}
            />
          </h2>
        </div>
        <div ref={gridRef} className="services__grid">
          {SERVICES.map((item, i) => (
            <TabCard
              key={item.eyebrow}
              cardRef={(el) => (cardRefs.current[i] = el)}
              className="service-card"
              tabColor={item.glowColor}
              tab={item.title}
              title={item.eyebrow}
              body={item.body}
              glow={<div className={`card-glow card-glow--${item.glowColor}`} aria-hidden="true" />}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

function ProcessStack() {
  // Below 768px .process (this outer <section>) is the scroll-room spacer
  // and .process__section itself is the sticky element — see its comment in
  // home.css. At 768px+ headline and cards go back to two independent
  // side-by-side sticky columns, each paced by its own spacer —
  // .process__cards-wrap is the one that matters there.
  const spacerRef = useRef(null);
  const wrapRef = useRef(null);
  // .process__cards' own rendered height — read for the centering math
  // below, not the scroll pacing: below 768px that box is only whatever
  // space flex leaves it after .process__aside's height (in the same
  // pinned section), not a full viewport, so centering the stack against
  // the raw window height would sit it too low.
  const cardsBoxRef = useRef(null);
  const cardRefs = useRef([]);
  const indicatorRefs = useRef([]);

  // Cards are position:absolute inside .process__cards; this listener
  // drives each one's entrance (--card-arrive, 0→1, consumed by a
  // translateY in CSS), its recede-when-covered shrink (--card-scale), and a
  // shared --stack-shift that centers the whole assembled stack vertically
  // — all written straight onto the elements via refs, not React state, so
  // scrolling never triggers a re-render.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const STEP = 0.045; // shrink applied per fully-arrived covering card
    let frame = null;
    // Cached like Services' own sp600, not read fresh every measure() call —
    // window.innerHeight shrinks/grows live as a mobile browser's address
    // bar collapses/expands, and measure() reruns on every scroll frame, so
    // reading it directly here would let the arrival/shrink math jump mid-
    // gesture (or right as a scroll's momentum tail coincides with the
    // toolbar settling) even with .process's own height already fixed to
    // svh above. Only refreshed on a real resize (width actually changed —
    // an orientation flip or window resize), not the height-only change a
    // toolbar transition produces.
    let vh = window.innerHeight;
    let lastWidth = window.innerWidth;

    const measure = () => {
      frame = null;
      const cards = cardRefs.current;
      const cardsBox = cardsBoxRef.current;
      if (!cards.length || !cardsBox) return;

      const mobile = window.innerWidth < 768;
      const spacer = mobile ? spacerRef.current : wrapRef.current;
      if (!spacer) return;

      const rect = spacer.getBoundingClientRect();
      // How far we've scrolled into the pinned region, clamped to its own
      // scrollable extent (the spacer is one viewport taller than that,
      // since the sticky element it holds always occupies a full viewport).
      const scrolled = Math.min(Math.max(0, -rect.top), Math.max(0, rect.height - vh));

      // Every card — including the first — gets one viewport-height's worth
      // of scroll, back to back, to slide up from below into its resting
      // (stacked) position, so the whole thing arrives one card at a time.
      const arrival = cards.map((_, i) => {
        const start = i * vh;
        return Math.min(1, Math.max(0, (scrolled - start) / vh));
      });

      // Which card is currently "on top" of the stack, as a continuous
      // blend rather than a discrete index: card i is the topmost one for
      // as long as it's arrived but the next card hasn't started covering
      // it yet, so its own "active" weight is how much of its own arrival
      // *isn't* already eaten by the next card's — arrival[i] - arrival[i+1]
      // (0 for the last card, which has nothing covering it). This telescopes
      // to exactly one card owning ~all the weight at rest, and crossfades
      // smoothly between the two involved while one is arriving over the
      // other — see .process__indicator-seg in home.css for what consumes it.
      indicatorRefs.current.forEach((seg, i) => {
        if (!seg) return;
        const next = i + 1 < arrival.length ? arrival[i + 1] : 0;
        const weight = reduce ? (i === arrival.length - 1 ? 1 : 0) : Math.min(1, Math.max(0, arrival[i] - next));
        seg.style.setProperty("--indicator-active", weight.toFixed(3));
      });

      // Resting geometry (CSS `top` + rendered height) is unaffected by the
      // transform below, so this reads the assembled stack's true extent —
      // from the first card's resting top to the last card's resting bottom.
      // Desktop centers that block within .process__cards' own box; mobile
      // aligns it to the top instead (just cancels out the stairstepped
      // resting `top` offset so the first card's top edge sits flush at 0).
      const cardsBoxH = cardsBox.offsetHeight;
      const first = cards[0];
      const last = cards[cards.length - 1];
      let shift = 0;
      if (first && last) {
        const stackTop = first.offsetTop;
        const stackHeight = last.offsetTop + last.offsetHeight - stackTop;
        shift = mobile ? -stackTop : (cardsBoxH - stackHeight) / 2 - stackTop;
      }

      cards.forEach((card, i) => {
        if (!card) return;
        card.style.setProperty("--card-arrive", reduce ? "1" : String(arrival[i]));
        card.style.setProperty("--stack-shift", `${shift}px`);
        // See .process-card's comment in home.css — starts the entrance
        // exactly one cardsBoxH below rest, not a flat 100svh, so there's no
        // dead scroll spent closing a gap bigger than the box actually is.
        card.style.setProperty("--card-travel", `${cardsBoxH}px`);
        let shrink = 0;
        for (let j = i + 1; j < arrival.length; j++) shrink += arrival[j] * STEP;
        card.style.setProperty("--card-scale", reduce ? "1" : String(1 - shrink));
      });
    };

    const onScroll = () => {
      if (reduce) return;
      if (frame === null) frame = requestAnimationFrame(measure);
    };
    const onResize = () => {
      // Width-only check: a real orientation flip/window resize always
      // changes innerWidth too, whereas a mobile toolbar collapsing or
      // expanding only ever changes innerHeight — so this refreshes the
      // cached vh for the former and ignores the latter.
      if (window.innerWidth !== lastWidth) {
        lastWidth = window.innerWidth;
        vh = window.innerHeight;
      }
      if (frame === null) frame = requestAnimationFrame(measure);
    };

    // The settled resting layout (centering, mainly) still runs once even
    // under prefers-reduced-motion — only the scroll-driven entrance itself
    // is skipped (see onScroll/measure above, --card-arrive/--card-scale
    // forced to their settled "1" instead).
    measure();
    document.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      if (frame !== null) cancelAnimationFrame(frame);
      document.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, []);

  return (
    <section className="process" ref={spacerRef}>
      <div className="process__section">
        <div className="process__aside-wrap">
          <div className="process__aside">
            {/* node 747:5801, "Frame 126" — 3 segments, one per
                PROCESS_STEPS card; the active one (the card currently on
                top of the stack) widens/darkens, driven by
                --indicator-active per segment from the scroll listener
                above. */}
            <div className="process__indicator" aria-hidden="true">
              {PROCESS_STEPS.map((step, i) => (
                <span key={step.tab} ref={(el) => (indicatorRefs.current[i] = el)} className="process__indicator-seg" />
              ))}
            </div>
            <div className="process__intro">
              <h2 className="section-headline tone-dark">
                <ScrollCharFlipRevealText text={"The process built \n around your goals"} repeat />
              </h2>
            </div>
          </div>
        </div>

        <div ref={wrapRef} className="process__cards-wrap">
          <div ref={cardsBoxRef} className="process__cards">
            {PROCESS_STEPS.map((step, i) => (
              <TabCard
                key={step.tab}
                cardRef={(el) => (cardRefs.current[i] = el)}
                className="process-card"
                tabColor={step.tabColor}
                tab={step.tab}
                secondaryTab={step.week}
                title={step.title}
                body={step.body}
                titleTone="dark"
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

// Work — "Featured work", node 676:1764. Pinned-viewport horizontal scroll:
// the outer <section id="work"> (ref'd as the "spacer") is given extra
// height in JS so that scrolling into it doesn't just scroll the page past
// it — .work__pin (position:sticky, 100svh, overflow:hidden) holds the
// header + card track fixed on screen for as long as the spacer's extra
// height lasts, and .work__track's translateX tracks how far you've
// scrolled *into* the spacer, reversible scrolling back up.
//
// The move itself is modeled on simple-horizontal-cards.webflow.io (a
// working reference for exactly this pattern): it drives its track via
// Webflow's SCROLL_PROGRESS interaction as a TRANSFORM_MOVE with a
// percentage OF THE TRACK'S OWN WIDTH, not a pixel offset — a hardcoded
// ratio there, since their card count/widths are fixed. Here the final
// (progress 1) position is calc(-100% + 100dvw): the track's own full
// width shifted left (-100%, of itself — .work__track is width:max-content
// in home.css, so 100% of it IS first-card-to-last-card), then shifted
// back right by exactly one viewport width (100dvw) — which lands the
// track's right edge (its last card) flush with the viewport's right edge,
// automatically, at whatever the real card count/widths/viewport size
// happen to be, no JS-computed ratio needed for the target itself. Mixing
// % and dvw like this still resolves natively in the browser's own layout
// engine at paint time (each term against its own reference — % against
// the track's current width, dvw against the current viewport), so it
// can't drift out of sync with a stale JS measurement the way three
// earlier px-based attempts here did (scrollWidth being unreliable on a
// non-scroll-container element; offsetLeft being relative to the nearest
// *positioned* ancestor, .work, not .work__track itself, which silently
// shifted once .work__inner's max-width:1440px cap stopped applying).
//
// overflowPx (the spacer's actual scroll-room, still needed since document
// scroll is unavoidably px-based) is track.offsetWidth compared against
// .work__inner's own clientWidth — never scrollWidth, never
// offsetLeft/getBoundingClientRect position, only ever "how wide is this
// one element," which has none of the pitfalls those did.
//
// Below MOBILE_BREAKPOINT, all of the above (JS-measured overflowPx,
// JS-set spacer height) is bypassed in favor of a dedicated invisible
// sibling, .work__mobile-trigger (mobileTriggerRef) — a fixed 200dvh
// block with no visible content. Two reasons: the measured-overflow
// distance was too short for a phone's much burstier touch-scroll
// momentum (a single flick could blow through it near-instantly); and
// unlike overflowPx it's a plain, designer-tunable number, independent of
// how many cards are in the track. The spacer gets no inline height on
// mobile at all — its real height is just its children's natural flow
// height (.work__pin's 100svh + the trigger's 200dvh), so the trigger's
// CSS height is simultaneously what reserves the pin's scroll-room AND
// what progress is measured against, with no JS math tying the two
// together. Progress itself is read straight off the trigger's own
// position against the viewport's *bottom* edge (not spacer-top, like
// desktop): 0 once its top edge reaches the viewport bottom (about to
// scroll into view from below — this coincides with the exact moment the
// pin starts sticking, since the trigger sits directly below it in the
// flow), 1 once its bottom edge reaches the viewport bottom (its full
// 200dvh has scrolled past — which is also exactly when the spacer runs
// out and the pin releases).

function WorkSection({ filtered, activeTags, setActiveTags, toggleTag, onOpenProject, onOpenWorkArchive }) {
  const spacerRef = useRef(null);
  const trackRef = useRef(null);
  const mobileTriggerRef = useRef(null);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const MOBILE_BREAKPOINT = 768; // matches .work-card's own mobile breakpoint (home.css)
    let overflowPx = 0; // desktop only: real first-card-to-last-card overflow, in px
    let mobile = false;
    let frame = null;
    // Cached, not read fresh in tick()'s mobile branch below — see Services'
    // ladder/scale effect for why: window.innerHeight changes live as a
    // mobile browser's address bar shows/hides, which would otherwise jump
    // this section's horizontal-scroll progress exactly when that happens
    // mid-gesture. Only refreshed on a real resize (width actually
    // changed), in onResize below.
    let vh = window.innerHeight;
    let lastWidth = window.innerWidth;

    // Re-measured on resize and whenever the filtered project count changes
    // (fewer/wider/narrower cards means a different overflow), not every
    // frame — this is a layout read, so doing it in the scroll tick itself
    // would force a reflow on every scroll event.
    const measure = () => {
      const track = trackRef.current;
      const spacer = spacerRef.current;
      if (!track || !spacer) return;
      mobile = window.innerWidth <= MOBILE_BREAKPOINT;
      if (mobile) {
        // Clear any desktop-set inline height — .work__mobile-trigger's own
        // CSS height provides the spacer's scroll-room here instead.
        spacer.style.height = "";
        return;
      }
      // .work__track is width:max-content (home.css) — its own offsetWidth
      // IS the true first-card-to-last-card content width now, no more
      // summing children by hand. The "visible" width to compare against is
      // .work__inner (track's own parent), not the track itself, since the
      // track no longer stays narrow on its own — .work__pin's
      // overflow:hidden, one level up, is what actually clips it.
      const visibleWidth = track.parentElement ? track.parentElement.clientWidth : track.clientWidth;
      overflowPx = Math.max(0, track.offsetWidth - visibleWidth);
      spacer.style.height = `calc(100svh + ${overflowPx}px)`;
    };

    const render = (progress) => {
      const track = trackRef.current;
      if (!track) return;
      // Final position (progress 1) is
      // -100% + min(1440px, 100dvw) - section-padding — track's own full
      // width shifted left, shifted back right by whichever is smaller of
      // one viewport width or 1440px (matching .work__inner's own
      // max-width:1440px cap, so this stops growing past the same point
      // the content column itself does — plain 100dvw would keep shifting
      // further right past 1440px, overshooting the column's real right
      // edge on very wide screens), then pulled back in by the section's
      // own inset so the last card ends with the same breathing room the
      // first one starts with. The whole sum is multiplied by progress as
      // one unit (not each term separately) so it's still a continuous
      // scrub from 0 up to that final value, not a jump.
      track.style.transform = reduce
        ? "translateX(0px)"
        : `translateX(calc((-100% + min(1440px, 100dvw) - (var(--section-padding) * 1)) * ${progress.toFixed(4)}))`;
    };

    const tick = () => {
      frame = null;
      const track = trackRef.current;
      if (!track) return;

      let progress = 0;
      if (mobile) {
        const trigger = mobileTriggerRef.current;
        if (trigger) {
          const rect = trigger.getBoundingClientRect();
          progress = rect.height > 0 ? (vh - rect.top) / rect.height : 0;
          progress = Math.min(Math.max(progress, 0), 1);
        }
      } else {
        const spacer = spacerRef.current;
        if (spacer) {
          const scrolled = Math.min(Math.max(0, -spacer.getBoundingClientRect().top), overflowPx);
          progress = overflowPx > 0 ? scrolled / overflowPx : 0;
        }
      }
      render(progress);
    };

    const onScroll = () => {
      if (frame === null) frame = requestAnimationFrame(tick);
    };
    const onResize = () => {
      if (window.innerWidth !== lastWidth) {
        lastWidth = window.innerWidth;
        vh = window.innerHeight;
      }
      measure();
      if (frame === null) frame = requestAnimationFrame(tick);
    };

    measure();
    tick();
    document.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      if (frame !== null) cancelAnimationFrame(frame);
      document.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
    // filtered.length: re-measure overflow when the visible card count
    // changes (a filter toggle can add/remove cards mid-scroll).
  }, [filtered.length]);

  return (
    <section id="work" className="work" ref={spacerRef}>
      <div className="work__pin">
        <div className="work__inner">
          <div className="work__header">
            <div className="work__title">
              <div className="work__heading">
                <p className="section-headline tone-light">Explore my projects</p>
              </div>
              {/* Not part of node 676:1512 — added so /work (node 676:1763's
                  standalone archive page) is actually reachable from
                  somewhere in the UI, not just a direct URL. .btn-primary
                  is the same button already used for "View project" on
                  this section's own cards below. */}
              <button type="button" className="btn-primary work__view-all" onClick={onOpenWorkArchive}>
                View all work
              </button>
            </div>
            <div className="work__filters">
              <p className="work__filters-label">Filter projects</p>
              <div className="work__pills">
                {activeTags.length > 0 && (
                  <button className="work__clear" onClick={() => setActiveTags([])}>
                    Clear Filters
                  </button>
                )}
                {TAG_ORDER.map((tag) => (
                  <button
                    key={tag}
                    className={`pill-outline${activeTags.includes(tag) ? " pill-outline--active" : ""}`}
                    onClick={() => toggleTag(tag)}
                  >
                    {TAGS[tag].label}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {filtered.length === 0 ? (
            <div className="py-20 text-center" style={{ color: MUTED, fontFamily: "'Zalando Sans', sans-serif", fontSize: 15 }}>
              No projects match that combination of tags yet.
            </div>
          ) : (
            <div className="work__track" ref={trackRef}>
              {filtered.map((p) => (
                // A <div> here, not <button> — the "View project" CTA below is
                // its own real <button>, and HTML forbids nesting interactive
                // controls inside one another.
                <div
                  key={p.id}
                  className="work-card"
                  role="button"
                  tabIndex={0}
                  onClick={() => onOpenProject(p.id)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      onOpenProject(p.id);
                    }
                  }}
                >
                  <div className="work-card__image">
                    {/* coverImage is the shot for this list — project-page
                        header uses its own separate introImage instead (see
                        ProjectPage's hero below). */}
                    {p.coverImageSquare ? (
                      // A real square export below 768px instead of letting
                      // object-fit:cover crop the wide cover down — matches
                      // .work-card__image's own aspect-ratio switch at the
                      // same breakpoint (see home.css).
                      <picture>
                        <source media="(max-width: 768px)" srcSet={p.coverImageSquare} />
                        <img src={p.coverImage} alt={p.coverAlt || p.name} loading="lazy" />
                      </picture>
                    ) : (
                      <img src={p.coverImage} alt={p.coverAlt || p.name} loading="lazy" />
                    )}
                  </div>
                  {/* Own row between the image and the body, not stacked
                      above the title inside .work-card__body. Flat k-900/
                      k-700/k-400 pill, same for every tag — not the
                      accent-per-tag color the project page's own chips use
                      (WORK_TAG_ACCENT), since this section is dark now but
                      isn't wired up to per-tag accent colors. */}
                  <div className="work-card__tags">
                    {p.tags.map((t) => (
                      <span key={t} className="work-card__tag">
                        {TAGS[t].label}
                      </span>
                    ))}
                  </div>
                  <div className="work-card__body">
                    <div className="work-card__info">
                      <p className="work-card__title">{p.name}</p>
                    </div>
                    <button
                      type="button"
                      className="btn-secondary"
                      onClick={(e) => {
                        // Same destination as clicking the card itself —
                        // this button just makes that action discoverable/
                        // explicit rather than relying on the whole card
                        // being a click target. stopPropagation only
                        // avoids firing the card's own onClick a second
                        // time on top of this one.
                        e.stopPropagation();
                        onOpenProject(p.id);
                      }}
                    >
                      View project
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
      {/* Mobile-only measurement sibling — see WorkSection's effect comment
          above the pin/track description. Empty on purpose: its own
          getBoundingClientRect() against the viewport bottom is all it's
          for, nothing renders inside it. */}
      <div className="work__mobile-trigger" ref={mobileTriggerRef} aria-hidden="true" />
    </section>
  );
}

// Curated subset for the homepage's Featured Work strip — everything else
// (Injecting, Marina Dorćol, ...) is still reachable from the full /work
// archive, just not duplicated here.
const HOME_FEATURED_IDS = ["fotona", "stroomkaart", "nrg-cockpit", "social-media-design"];
const HOME_FEATURED_PROJECTS = HOME_FEATURED_IDS.map((id) => PROJECTS.find((p) => p.id === id)).filter(Boolean);

// Display order for the /work archive — independent of PROJECTS' own
// declaration order in the array above, same approach as
// HOME_FEATURED_IDS/HOME_FEATURED_PROJECTS just above.
const WORK_ORDER_IDS = [
  "fotona",
  "stroomkaart",
  "injecting",
  "nrg-cockpit",
  "marina-dorcol",
  "social-media-design",
  "newsletters",
  "madera",
  "compass-project",
  "edil-italiana",
];
const WORK_ORDERED_PROJECTS = WORK_ORDER_IDS.map((id) => PROJECTS.find((p) => p.id === id)).filter(Boolean);

function Home({ onOpenProject, onOpenWorkArchive, activeTags, setActiveTags, toggleTag, onCta, heroReady }) {
  const filtered = useMemo(() => {
    if (activeTags.length === 0) return HOME_FEATURED_PROJECTS;
    return HOME_FEATURED_PROJECTS.filter((p) => p.tags.some((t) => activeTags.includes(t)));
  }, [activeTags]);

  const scrollToWork = () => {
    document.getElementById("work")?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  // Decorative hero__closing-bands: scaleX scrubs continuously between 0
  // and 1 as .hero__closing crosses a scroll window, rather than
  // triggering once via a CSS transition — start point is the bands' own
  // top at 80% down the viewport (20% from the bottom, same convention the
  // Services ladder uses); end point is their *bottom* edge reaching 0%
  // from the bottom of the screen, i.e. flush with the bottom of the
  // viewport. Both keyed off the same top-position measurement for a
  // single continuous progress value — endY is just wherever that top edge
  // has to be for the bottom edge (top + the box's own height) to land
  // exactly at vh, rather than a flat percentage like startY is. Scrolling
  // back up runs the same math in reverse, since target is a continuous
  // function of the section's live position, not a one-shot flag — there's
  // nothing to "reset", it just tracks backward on its own. LERP smooths
  // frame-to-frame steps the same way the Services/footer scroll effects
  // do; --band-scale (not a transitioned class) is what
  // .hero__closing-band's transform in home.css actually reads.
  const bandsRef = useRef(null);
  useEffect(() => {
    if (typeof window === "undefined") return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    // See Services' ladder/scale effect for why coarse pointers skip LERP
    // (and, below, the perpetual rAF loop itself) too.
    const isTouch = window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
    const skipLerp = reduce || isTouch;

    const START_PCT = 0.8;
    const LERP = 0.22;
    let current = 0;
    let frame = null;
    // Cached, not read fresh in measure() — see Services' ladder/scale
    // effect for why: window.innerHeight changes live as a mobile browser's
    // address bar shows/hides, which would otherwise jump this animation's
    // computed progress exactly when that happens mid-scroll.
    let vh = window.innerHeight;
    let lastWidth = window.innerWidth;

    const measure = () => {
      frame = null;
      const bands = bandsRef.current;
      if (bands) {
        const rect = bands.getBoundingClientRect();
        const startY = vh * START_PCT;
        const endY = vh - rect.height;
        const target = Math.min(1, Math.max(0, (startY - rect.top) / (startY - endY)));
        current = skipLerp ? target : current + (target - current) * LERP;
        bands.style.setProperty("--band-scale", current.toFixed(4));
      }
    };

    // Event-driven once LERP is skipped, not an unconditional self-
    // rescheduling rAF loop — see Services' ladder/scale effect for the
    // full reasoning.
    if (skipLerp) {
      measure();
      const onScroll = () => {
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      const onResize = () => {
        if (window.innerWidth !== lastWidth) {
          lastWidth = window.innerWidth;
          vh = window.innerHeight;
        }
        if (frame === null) frame = requestAnimationFrame(measure);
      };
      document.addEventListener("scroll", onScroll, true);
      window.addEventListener("resize", onResize);
      return () => {
        if (frame !== null) cancelAnimationFrame(frame);
        document.removeEventListener("scroll", onScroll, true);
        window.removeEventListener("resize", onResize);
      };
    }

    const onResizeDesktop = () => {
      if (window.innerWidth !== lastWidth) {
        lastWidth = window.innerWidth;
        vh = window.innerHeight;
      }
    };
    const tick = () => {
      measure();
      frame = requestAnimationFrame(tick);
    };
    window.addEventListener("resize", onResizeDesktop);
    frame = requestAnimationFrame(tick);
    return () => {
      if (frame !== null) cancelAnimationFrame(frame);
      window.removeEventListener("resize", onResizeDesktop);
    };
  }, []);

  // The hero's two headline lines and the separator between them are one
  // sequence, not three independently-guessed delays: each stage's delay
  // is computed from when line 1 actually finishes revealing
  // (charFlipRevealMs), so line 2 always starts right as line 1 completes
  // rather than on a guessed fixed delay.
  const HERO_LINE_1 = "Hello, I'm Luka, a freelance brand and graphic designer";
  const HERO_LINE_2 = "I help companies build trust and credibility through visual communication";
  const HERO_LINE_1_DELAY = 0;
  const heroLine2Delay = HERO_LINE_1_DELAY + charFlipRevealMs(HERO_LINE_1);

  return (
    <div>
      {/* Hero — Figma "Elan sajt" file, Home/Hero node 675:980. */}
      <section className="hero">
        <div className="hero__content">
          {/* No animation of its own, deliberately — just sits there
              normally the whole time, blank/hidden behind the loading
              screen's own mask like everything else under it, and plainly
              visible the instant that mask clears past it. */}
          <SiteNav onLogoClick={scrollToWork} onWorkClick={onOpenWorkArchive} onCta={onCta} />

          {/* Two independent lines, node 718:1863 — a 12-col grid (each line
              spans 1/10) rather than one headline block, so they're free to
              wrap and stagger-reveal on their own. AutoCharFlipRevealText,
              not ScrollCharFlipRevealText — these have to play as soon as
              they're allowed to (heroReady), full stop, not only once they
              also happen to satisfy a scroll-position check; the hero
              headline is right at the top of the page, so whether that
              check passes at a given moment isn't something it should
              depend on at all. */}
          <div className="hero__headline-grid">
            <div className="hero__headline-row">
              <h1 className="hero__headline">
                {heroReady && (
                  <AutoCharFlipRevealText
                    text={HERO_LINE_1}
                    delay={HERO_LINE_1_DELAY}
                    accentWords={["freelance", "designer"]}
                  />
                )}
              </h1>
            </div>
            <div className="hero__headline-row">
              <p className="hero__headline">
                {heroReady && (
                  <AutoCharFlipRevealText
                    text={HERO_LINE_2}
                    delay={heroLine2Delay}
                    accentWords={["trust", "credibility"]}
                  />
                )}
              </p>
            </div>
            {/* Node 803:2499 — bordered meta row closing out the headline
                grid: the service list on the left, and (client request,
                replacing Figma node 804:2513's own flat placeholder
                rectangle) a small looping version of the logo mark — same
                mosaic as the loading screen, each block pulsing in place
                on its own stagger via .elan-mark__block in home.css. */}
            <div className="hero__meta-row">
              <p className="hero__meta-tags">
                Brand <span className="hero__meta-divider">|</span> Graphic <span className="hero__meta-divider">|</span> Web Design
              </p>
              <div className="hero__meta-swatch" aria-hidden="true">
                <ElanLogoMark height={20} symbolOnly animatePulse monochrome="var(--k-400)" />
              </div>
            </div>
          </div>
        </div>

        <div className="hero__closing">
          {/* Decorative bands, behind the headline (z-index in home.css) —
              3 flex-row divs, no gap, first/third 60% width, middle 40%,
              all 100% height; combined width (160%) is intentional, flex's
              default shrink then compresses all three proportionally to
              fit 100%, preserving the 3:2:3 ratio. */}
          <div ref={bandsRef} className="hero__closing-bands" aria-hidden="true">
            <div className="hero__closing-band hero__closing-band--outer" />
            <div className="hero__closing-band hero__closing-band--inner" />
            <div className="hero__closing-band hero__closing-band--outer" />
          </div>
          <div className="hero__closing-grid">
            {/* Node 726:2233 — the headline plus its eyebrow line (803:2508),
                sharing this one grid item/column so the eyebrow stays pinned
                to the headline's own measure instead of the full grid width.
                Both use CharFlipRevealText (the same scroll-scrubbed variant,
                not the mount-triggered Auto one) so the eyebrow flips in
                alongside the headline as this section scrolls into view,
                rather than sitting there static. */}
            <div className="hero__closing-content">
              <p className="eyebrow hero__closing-eyebrow hero__closing-eyebrow--top">
                <CharFlipRevealText text="Strategy-led · Detail-focused" />
              </p>
              <h2 className="section-headline hero__closing-headline">
                <CharFlipRevealText
                  text="My approach is strategic, built around your company, its needs and values"
                  accentWords={["strategic", "needs", "values"]}
                />
              </h2>
            </div>
          </div>
        </div>

        <Services />
      </section>

      {/* Process + Featured work share one wrapper in Figma (node 676:1512)
          — a single rounded k-100 panel with one diamond-pattern background
          image behind both sections, not two separately-backed sections. */}
      <div className="process-work">
        <ProcessStack />

        <WorkSection
          filtered={filtered}
          activeTags={activeTags}
          setActiveTags={setActiveTags}
          toggleTag={toggleTag}
          onOpenProject={onOpenProject}
          onOpenWorkArchive={onOpenWorkArchive}
        />
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Project detail                                                     */
/* ------------------------------------------------------------------ */

// Reusable case-study template — node 676:5139. Every project in PROJECTS
// (id/name/category/tagline/description/tags/coverImage/sections) renders
// through this same component; nothing here is Fotona- or COMPASS-specific,
// it's just the data that differs.
function ProjectPage({ project, onBack, onOpenProject }) {
  const [heroImgFailed, setHeroImgFailed] = useState(false);

  useEffect(() => {
    setHeroImgFailed(false);
    document.body.scrollTo({ top: 0 }); // body scrolls now, not the window — see App()'s comment
  }, [project.id]);

  const currentIndex = PROJECTS.findIndex((p) => p.id === project.id);
  const next = PROJECTS[(currentIndex + 1) % PROJECTS.length];

  return (
    <div className="case-page">
      {/* Hero — full-bleed intro image. introImage is the shot made for this
          full-bleed header; falls back to coverImage (the homepage-list
          shot) for projects that don't set a separate one. */}
      <section className="case-hero">
        <div className="case-hero__image">
          {(project.introImage || project.coverImage) && !heroImgFailed ? (
            <img src={project.introImage || project.coverImage} alt={project.introAlt || project.name} onError={() => setHeroImgFailed(true)} />
          ) : (
            <AbstractMark id={project.id + "-hero"} tags={project.tags} dense />
          )}
        </div>
      </section>

      {/* Body — node 742:3072/676:5139: ALL text (the intro paragraph, then
          every section's body) lives together in one floating card, and ALL
          media for the project follows afterward as its own separate
          full-bleed stack — the two never interleave. A section's body can
          be one paragraph or several {heading, text} blocks; any media a
          block carries (COMPASS-style step-by-step) is pulled out and
          appended to the shared media stack in the same order rather than
          breaking up the card's text flow. */}
      <div className="case-sections">
        <div className="case-intro-card">
          <div className="case-intro-card__top">
            <button className="case-intro-card__back" onClick={onBack}>
              <ArrowLeft size={11} />
              All projects
            </button>
            <div className="case-intro-card__tags">
              {/* Filled, not .pill-outline's plain transparent look (that
                  one's shared with the Work section's filter buttons) —
                  matches node 742:3072's intro-card tags: k-900 bg, k-700
                  border, flat k-400 text for every tag. */}
              {project.tags.map((t) => (
                <span key={t} className="case-intro-card__tag">
                  {TAGS[t].label}
                </span>
              ))}
            </div>
          </div>

          <h1 className="case-title">{project.name}</h1>

          <Paragraph heading="Introduction" text={project.description} />

          {project.sections.map((section) => {
            const meta = TAGS[section.tag];
            return Array.isArray(section.body) ? (
              // A block's own heading (e.g. "Challenge"/"Solution") wins;
              // the first block falls back to the section's tag label
              // ("Visual Identity") when it doesn't have one of its own.
              section.body.map((block, bi) => (
                <Paragraph key={`${section.tag}-${bi}`} heading={block.heading || (bi === 0 ? meta.label : null)} text={block.text} />
              ))
            ) : (
              <Paragraph key={section.tag} heading={meta.label} text={section.body} />
            );
          })}
        </div>

        <div className="case-media-stack">
          {project.sections.map((section) => {
            // Flatten each block's own media in with the section's trailing
            // media — same combined set as before, just no longer split up
            // by the text blocks it used to sit between.
            const blockMedia = Array.isArray(section.body)
              ? section.body.flatMap((block) => block.media || [])
              : [];
            const blocks = [
              ...blockMedia,
              ...(section.media || (blockMedia.length === 0 && project.coverImage ? [{ type: "full", src: project.coverImage }] : [])),
            ];
            // "<project name> — <category>" rather than just the project
            // name alone — every image in a section was sharing one
            // identical, non-descriptive alt text before this. Still not a
            // true per-image description (that needs eyes on each actual
            // photo), but at least distinguishes which part of the project
            // a given image belongs to.
            const sectionAlt = `${project.name} — ${TAGS[section.tag]?.label || section.tag}`;
            return (
              <SectionMedia
                key={section.tag}
                id={project.id}
                tag={section.tag}
                alt={sectionAlt}
                blocks={blocks.length > 0 ? blocks : DEFAULT_MEDIA}
              />
            );
          })}
        </div>
      </div>

      {/* Next project */}
      <button className="case-next" onClick={() => onOpenProject(next.id)}>
        <div className="case-next__inner">
          <div>
            <p className="eyebrow tone-muted case-next__label">Next project</p>
            <p className="section-headline tone-light case-next__name">{next.name}</p>
          </div>
          <ArrowUpRight size={22} className="case-next__arrow" />
        </div>
      </button>
    </div>
  );
}

