// Standalone /privacy page — not part of the case-study template (no hero,
// tags, or media stack), so it doesn't reuse .case-sections/.case-intro-card
// (those two are hero-coupled: .case-sections' -100px margin-top exists
// specifically to pull the intro card up over a hero image this page
// doesn't have). Reuses Paragraph/.case-title/.case-intro-card__back
// directly instead, inside its own simple centered column.
function PrivacyPolicy({ onBack }) {
  useEffect(() => {
    document.body.scrollTo({ top: 0 });
  }, []);

  return (
    <div className="case-page">
      <div className="privacy-page">
        <button className="case-intro-card__back privacy-page__back" onClick={onBack}>
          <ArrowLeft size={11} />
          Back home
        </button>

        <h1 className="case-title">Privacy Policy</h1>

        <Paragraph text="This site collects the e-mail address you submit through the contact form, solely to respond to your inquiry." />
        <Paragraph
          heading="What this site collects"
          text="The contact form asks for your e-mail address only — no name, phone number, or other personal information is requested."
        />
        <Paragraph
          heading="How it's used"
          text="Your message and e-mail address are used only to read and reply to your inquiry, typically within two working days. They aren't used for marketing, added to a mailing list, or shared with anyone beyond what's needed to respond to you."
        />
        {/* Manual Paragraph markup (not the component) — this is the one
            block that needs a real link to Formspree's own policy rather
            than plain text. */}
        <div className="case-section-text">
          <p className="case-text-block__label">Third parties</p>
          <div className="case-text-block__body">
            <p className="body-text body-text--justify">
              Form submissions are processed by{" "}
              <a href="https://formspree.io/legal/privacy-policy/" target="_blank" rel="noopener noreferrer" style={{ color: "inherit" }}>
                Formspree
              </a>
              , a third-party service that delivers the message to my inbox — see their own privacy policy for how they handle that data.
            </p>
            <p className="body-text body-text--justify">This site doesn't use analytics, tracking cookies, or any other third-party service.</p>
          </div>
        </div>
        <Paragraph
          heading="Your rights"
          text="You can ask what information I have about you, or ask me to delete it, at any time — just email luka@elancreativestudio.com."
        />
      </div>
    </div>
  );
}

