/*  Work archive — node 676:1763                                       */
/* ------------------------------------------------------------------ */

// Standalone /work page — a plain 2-column grid of every project, separate
// from the homepage's own horizontal-scroll "Featured work" track
// (WorkSection). Each card's own layout (image, then a tag row + title on
// the left with "View project" pinned to the right) is node 701:1333's
// "procejt-card", not .work-card's — a different visual treatment on
// purpose, so it isn't reused here. Tags themselves reuse the project
// page's own .case-intro-card__tag chip rather than a third tag style.
function WorkArchive({ onOpenProject, activeTags, setActiveTags, toggleTag }) {
  useEffect(() => {
    document.body.scrollTo({ top: 0 });
  }, []);

  // Same filtering rule as the homepage's own WorkSection (Home) — shares
  // its activeTags/toggleTag state too (see App), so a filter picked on
  // one page holds if you navigate to the other.
  const filtered = useMemo(() => {
    if (activeTags.length === 0) return WORK_ORDERED_PROJECTS;
    return WORK_ORDERED_PROJECTS.filter((p) => p.tags.some((t) => activeTags.includes(t)));
  }, [activeTags]);

  return (
    <div className="case-page">
      <div className="work-archive">
        <div className="work-archive__header">
          <p className="eyebrow work-archive__eyebrow">Featured work</p>
          <p className="work-archive__headline">Take a look at what I've done</p>
          {/* node 798:2804 — same "Filter projects" pills as the homepage's
              own WorkSection, styled for this page's dark background
              (that one's .pill-outline is a light-bg white pill; this one's
              a transparent/bordered .work-archive__pill instead). */}
          <div className="work-archive__filters">
            <p className="work-archive__filters-label">Filter projects</p>
            <div className="work-archive__pills">
              {TAG_ORDER.map((tag) => (
                <button
                  key={tag}
                  type="button"
                  className={`work-archive__pill${activeTags.includes(tag) ? " work-archive__pill--active" : ""}`}
                  onClick={() => toggleTag(tag)}
                >
                  {TAGS[tag].label}
                </button>
              ))}
              {activeTags.length > 0 && (
                <button type="button" className="work-archive__clear" onClick={() => setActiveTags([])}>
                  Clear Filters
                </button>
              )}
            </div>
          </div>
        </div>
        {filtered.length === 0 ? (
          <p className="work-archive__empty">No projects match that combination of tags yet.</p>
        ) : (
        <div className="work-archive__grid">
          {filtered.map((p) => (
            <div
              key={p.id}
              className="archive-card"
              role="button"
              tabIndex={0}
              onClick={() => onOpenProject(p.id)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onOpenProject(p.id);
                }
              }}
            >
              <div className="archive-card__image">
                {/* Falls back to the same AbstractMark placeholder the
                    project-page hero uses (below) for projects whose real
                    cover shot isn't in yet — e.g. NRG Cockpit, images
                    pending. */}
                {p.coverImage ? (
                  <img src={p.coverImage} alt={p.coverAlt || p.name} loading="lazy" />
                ) : (
                  <AbstractMark id={p.id} tags={p.tags} />
                )}
              </div>
              <div className="archive-card__column">
                <div className="archive-card__tags">
                  {p.tags.map((t) => (
                    <span key={t} className="case-intro-card__tag">
                      {TAGS[t].label}
                    </span>
                  ))}
                </div>
                <div className="archive-card__row">
                  <p className="archive-card__title">{p.name}</p>
                  {/* A real <button>, not the outer div — same nested-
                      interactive-elements reasoning as .work-card's own
                      "View project" button (see WorkSection). */}
                  <button
                    type="button"
                    className="btn-primary archive-card__cta"
                    onClick={(e) => {
                      e.stopPropagation();
                      onOpenProject(p.id);
                    }}
                  >
                    View project
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  App                                                                 */
/* ------------------------------------------------------------------ */

// Timing: a beat before the fill starts, how long the logo then takes to
// fill white bottom-to-top, the pause once it's fully filled before the
// background lets go, and how long that background then takes to clear the
// viewport. LOADER_EASE (the fill) is a gentle symmetric ease-in-out;
// SLIDE_EASE (the mask reveal) is gentler still — closer to a sine curve,
// with even softer acceleration/deceleration at both ends — since it's a
// slower, longer motion that should read as an unhurried glide rather than
// a mechanical linear sweep.
const LOGO_HEIGHT = 120; // symbolOnly's viewBox is square (40/40 ratio, see ElanLogoMark), so this sets both height and width
const START_DELAY_MS = 1000;
const FILL_MS = 3000;
const HOLD_MS = 150;
const SLIDE_MS = 1100;
const LOADER_EASE = "cubic-bezier(0.65, 0, 0.35, 1)";
const SLIDE_EASE = "cubic-bezier(0.37, 0, 0.63, 1)";

function LoadingScreen({ onDone }) {
  const [filled, setFilled] = useState(false);
  const [sliding, setSliding] = useState(false);

  useEffect(() => {
    // A reload can land with the browser's own scroll-restoration already
    // partway down the page — the loading screen would then reveal
    // whatever was scrolled to instead of the hero, since nothing forces
    // it back to the top on its own. Forced unconditionally (not just on
    // the animated path below) and paired with locking scroll for as long
    // as this is on screen, so the position it lands on can't drift again
    // before the reveal actually happens. body scrolls now, not the
    // window/html — see App()'s comment on why.
    document.body.scrollTo(0, 0);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const unlock = () => {
      document.body.style.overflow = prevOverflow;
    };

    const reduce =
      window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) {
      onDone();
      return unlock;
    }

    const fillTimer = setTimeout(() => setFilled(true), START_DELAY_MS);
    const slideStart = START_DELAY_MS + FILL_MS + HOLD_MS;
    const slideTimer = setTimeout(() => setSliding(true), slideStart);
    // Matches SLIDE_MS so the overlay unmounts right as the wrapper finishes
    // collapsing away, not before or after.
    const doneTimer = setTimeout(onDone, slideStart + SLIDE_MS);
    return () => {
      unlock();
      clearTimeout(fillTimer);
      clearTimeout(slideTimer);
      clearTimeout(doneTimer);
    };
  }, [onDone]);

  // Reveal via mask instead of a transform: the whole container — dark
  // background and logo together, rendered normally, nothing scaled or
  // repositioned — gets a mask-image with a band centered on the middle
  // that grows outward toward both edges (--cut: 0% is fully covered,
  // nothing revealed yet; --cut: 50% is fully uncovered, the band having
  // reached both edges at once). Inside the growing band the mask is
  // transparent (hidden); outside it, still opaque (visible) — so as --cut
  // rises, the hero shows through starting at the center and the reveal
  // spreads outward toward the top and bottom edges simultaneously, and
  // nothing inside the container needs its own separate exit animation at
  // all. All of this
  // — the mask, the fill, the timings/eases — lives in home.css as
  // .loading-screen*/.loading-screen--sliding/.loading-screen__fill--filled
  // now, toggled by class instead of inline style, so it's inspectable/
  // tweakable in devtools. FILL_MS/SLIDE_MS/LOADER_EASE/SLIDE_EASE above are
  // still the source of truth for the *timers* (setTimeout needs real
  // numbers), but home.css's transition-duration/easing must be kept in
  // sync with them by hand — see the comment there.
  return (
    <div aria-hidden="true" className={`loading-screen${sliding ? " loading-screen--sliding" : ""}`}>
      <div className="loading-screen__mark">
        {/* Base layer: the mark in k-700, always fully visible — this is
            what still shows through wherever the white surface below hasn't
            filled in yet. */}
        <ElanLogoMark height={LOGO_HEIGHT} symbolOnly monochrome="var(--k-700)" />

        {/* The white "surface" — a real element rather than an actual
            ::after (a class can't target a pseudo-element from here either,
            but this stays a real element regardless), but the same idea:
            anchored to the bottom, height animates 0%→100%, and
            overflow:hidden clips it to that growing box. The white mark
            inside is rendered at full size but pinned to the *bottom* of
            this box, so as the box grows taller only progressively more of
            it — starting from its own bottom edge — comes into view,
            reading as the logo filling with white from the bottom up. */}
        <div className={`loading-screen__fill${filled ? " loading-screen__fill--filled" : ""}`}>
          <div className="loading-screen__fill-mark">
            <ElanLogoMark height={LOGO_HEIGHT} symbolOnly monochrome="#ffffff" />
          </div>
        </div>
      </div>
    </div>
  );
}

// Reads the current URL into a { view, id } route — real project URLs live
// at /work/<project-id>, /work alone is the standalone archive page,
// /privacy is the standalone privacy page, everything else (including an
// unrecognized project id) is home. Shared by the initial render and by the
// popstate handler below, so a direct link, a reload, and the browser's
// back/forward button all land on the same page a click on that project
// would have produced.
function routeFromLocation() {
  const path = window.location.pathname.replace(/\/+$/, "");
  const match = path.match(/^\/work\/([^/]+)$/);
  if (match && PROJECTS.some((p) => p.id === match[1])) {
    return { view: "project", id: match[1] };
  }
  if (path === "/work") {
    return { view: "workArchive" };
  }
  if (path === "/privacy") {
    return { view: "privacy" };
  }
  return { view: "home" };
}

export default function App() {
  const [route, setRoute] = useState(routeFromLocation);
  // Shared between Home's own "Featured work" filter pills and
  // WorkArchive's — a tag toggled on one persists if you navigate to the
  // other, rather than each page keeping its own separate filter state.
  const [activeTags, setActiveTags] = useState([]);
  const toggleTag = (tag) => {
    setActiveTags((prev) => (prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]));
  };
  // Only ever true for a direct/refreshed load that lands on home — the
  // preloader exists to mask the hero's own staggered text reveal
  // (heroReady below), which no other route has, so landing straight on
  // /work, /privacy, or a project page skips it entirely instead of
  // showing several seconds of blank overlay for no reason.
  const [loading, setLoading] = useState(() => route.view === "home");
  const finishLoading = useCallback(() => setLoading(false), []);

  // Keep the address bar and the browser's back/forward history in sync with
  // `route` — each project gets its own real, bookmarkable/shareable URL
  // instead of just an in-memory view switch.
  const openProject = (id) => {
    window.history.pushState({}, "", `/work/${id}`);
    setRoute({ view: "project", id });
  };
  const goHome = () => {
    window.history.pushState({}, "", "/");
    setRoute({ view: "home" });
    // Without this, navigating home from partway down a project page lands
    // on the home page at whatever scroll position the project page was at
    // — ProjectPage resets scroll on its own mount/id change, but nothing
    // did the same for the reverse direction.
    document.body.scrollTo(0, 0);
  };
  const goToPrivacy = () => {
    window.history.pushState({}, "", "/privacy");
    setRoute({ view: "privacy" });
    document.body.scrollTo(0, 0);
  };
  const goToWorkArchive = () => {
    window.history.pushState({}, "", "/work");
    setRoute({ view: "workArchive" });
    document.body.scrollTo(0, 0);
  };
  useEffect(() => {
    const onPopState = () => setRoute(routeFromLocation());
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);
  const scrollToContact = () => {
    document.getElementById("contact")?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const currentProject = route.view === "project" ? PROJECTS.find((p) => p.id === route.id) : null;

  // Per-page <title> — each project reads as its own page, not just a
  // different state of the home page. Also swaps the og:*/twitter:* tags
  // index.html sets statically for the homepage, so sharing a project link
  // previews that project instead of the generic homepage card — but this
  // is a best-effort fix, not a complete one: it only reaches unfurlers
  // that execute JS before reading <meta> tags (Slack/Discord/iMessage do;
  // Facebook's crawler notably does not). A fully robust per-route preview
  // needs server-side rendering or a prerender step, which this static
  // Vite build doesn't have.
  useEffect(() => {
    const title = currentProject
      ? `${currentProject.name} — Elan Creative Studio`
      : route.view === "privacy"
      ? "Privacy Policy — Elan Creative Studio"
      : route.view === "workArchive"
      ? "Work — Elan Creative Studio"
      : "Elan Creative Studio — Brand & Graphic Design";
    document.title = title;
    // The shared-link title is shorter than the browser-tab one on the
    // homepage specifically — matches index.html's own og:title/
    // twitter:title default. Every other route keeps using `title` for
    // both (their tab title already reads well as a share title too).
    const ogTitle = currentProject || route.view === "privacy" || route.view === "workArchive" ? title : "Brand and graphic design";

    const description = currentProject
      ? currentProject.description.length > 200
        ? currentProject.description.slice(0, 197).replace(/\s+\S*$/, "") + "…"
        : currentProject.description
      : route.view === "privacy"
      ? "How Elan Creative Studio collects and handles the information you submit through this site's contact form."
      : route.view === "workArchive"
      ? "Brand identity, print, and web design work by Elan Creative Studio."
      : "I help companies build visual identity that gain trust and credibility.";
    // Both the bundled-asset path (Vite emits e.g. "/assets/intro-xxx.webp")
    // and the "/og-image.png" default are root-relative — window.location.
    // origin turns either into a real absolute URL without hardcoding the
    // domain here, so this keeps working correctly even from a preview/
    // staging host, not just elancreativestudio.com.
    const path = currentProject
      ? `/work/${currentProject.id}`
      : route.view === "privacy"
      ? "/privacy"
      : route.view === "workArchive"
      ? "/work"
      : "/";
    const image = `${window.location.origin}${currentProject ? currentProject.introImage || currentProject.coverImage : "/og-image.png"}`;
    const url = `${window.location.origin}${path}`;

    const setMeta = (selector, content) => document.querySelector(selector)?.setAttribute("content", content);
    setMeta('meta[property="og:title"]', ogTitle);
    setMeta('meta[property="og:description"]', description);
    setMeta('meta[property="og:image"]', image);
    setMeta('meta[property="og:url"]', url);
    setMeta('meta[name="twitter:title"]', ogTitle);
    setMeta('meta[name="twitter:description"]', description);
    setMeta('meta[name="twitter:image"]', image);
    document.querySelector('link[rel="canonical"]')?.setAttribute("href", url);
  }, [currentProject, route.view]);

  return (
    <div style={{ backgroundColor: "var(--k-900)", minHeight: "100vh" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Zalando+Sans:ital,wght@0,100..900;1,100..900&display=swap');
        * { box-sizing: border-box; }
        /* html itself no longer scrolls at all — body does, explicitly, via
           its own height + overflow-y below. This is the actual fix for the
           scrollbar styling underneath: styling the TOP-LEVEL document
           scrollbar (html/the implicit viewport scroller) is unreliable in
           normal desktop Chrome/Chromium — it only reliably renders custom
           ::-webkit-scrollbar styling on a genuine, explicitly-scrollable
           element, not on the root viewport itself (this is why it only
           ever worked in Chrome's device-mode emulation, which renders
           scrollbars differently than normal desktop mode). Turning body
           into a regular scrollable element — same trick as a scrollable
           div anywhere else on the page — sidesteps that entirely.
           scroll-behavior moves here too, since body is the element that
           actually scrolls now. */
        html { height: 100%; overflow: hidden; }
        body { height: 100%; margin: 0; overflow-y: auto; overflow-x: hidden; scroll-behavior: smooth; }
        /* Black, thin, near-invisible scrollbar until actually needed. */
        body {
          scrollbar-width: none !important; /* Firefox */
          scrollbar-color: rgba(0, 0, 0, 0.25) transparent !important;
        }
        body::-webkit-scrollbar { width: 8px !important; height: 8px !important; }
        body::-webkit-scrollbar-track { background: transparent !important; }
        body::-webkit-scrollbar-thumb {
          background-color: rgba(0, 0, 0, 0.25) !important;
          border-radius: 999px !important;
          border: 2px solid transparent !important;
          background-clip: padding-box !important;
        }
        body::-webkit-scrollbar-thumb:hover {
          background-color: rgba(0, 0, 0, 0.4) !important;
          background-clip: padding-box !important;
        }
        ::selection { background: #2B6FDE; color: #FBFCFD; }
        button:focus-visible, a:focus-visible {
          outline: 2px solid #2B6FDE;
          outline-offset: 2px;
        }
        /* Pulls the footer mark out by exactly the page padding so it sits
           flush to the page edges. Mirrors px-6/md:px-10 and pb-6. */
        .footer-mark {
          left: -1.5rem;
          bottom: -1.5rem;
        }
        @media (min-width: 768px) {
          .footer-mark { left: -2.5rem; }
        }
        /* Black fill with a single bottom rule — no box, so the fields read as
           writing lines rather than containers. The fill stays opaque because
           the footer mark sits behind the form. */
        /* Footer headline + form: stacked by default, side by side from lg up.
           A later breakpoint than the form's own 768px switch, so the form
           isn't squeezed into two columns while also sharing a row with the
           headline at a size where there isn't room for both. */
        .footer-row {
          display: grid;
          grid-template-columns: 1fr;
          gap: 2.5rem;
          align-items: center;
        }
        @media (min-width: 1024px) {
          .footer-row {
            grid-template-columns: 1fr 1fr;
            gap: 4rem;
          }
        }
        /* Contact form grid — written as real CSS rather than Tailwind's
           col-span utilities, since that class isn't in this environment's
           prebuilt stylesheet and silently does nothing: Name/Email would
           default to span-1 as intended, but so would Message and the
           button, putting them side by side instead of each on its own row. */
        /* Case-study image grid — a plain 2 columns at every width, not 4 at
           wider screens: these hold individually-exported images (not one
           flattened composite), so the item count varies per section and
           doesn't assume a 2x2 arrangement the way "quad" once did.
           gap: var(--sp-200) — same value as .media-gap below, so quad
           blocks sit at the same spacing as the full/pair blocks around
           them. */
        .quad-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: var(--sp-200);
        }
        /* Opt-in modifier (block.cols === 4 in PROJECTS' media data) for a
           quad block that should read as one row of 4, not the shared
           2-column default above — e.g. Stroomkaart's 4 icon variants,
           which are one same-size set, not a taller 2x2 stack. */
        .quad-grid--4col {
          grid-template-columns: repeat(4, 1fr);
        }
        /* Shared gap for the project media column and its 2-up pair rows —
           matches .quad-grid's gap so every image-grid arrangement in a
           case study (full/pair/quad) sits at the same, tighter spacing. */
        .media-gap {
          gap: var(--sp-200);
        }
        .contact-grid {
          display: grid;
          grid-template-columns: 1fr;
          gap: 1rem;
        }
        @media (min-width: 768px) {
          .contact-grid { grid-template-columns: 1fr 1fr; }
        }
        .site-input {
          background-color: #000000;
          border: none;
          border-bottom: 1px solid rgba(251,252,253,0.22);
          border-radius: 0;
          padding: 14px 16px;
          color: ${PAPER};
          font-family: 'Zalando Sans', sans-serif;
          font-size: 16px;
          width: 100%;
          outline: none;
          transition: border-color 0.15s ease;
        }
        .site-input::placeholder { color: rgba(251,252,253,0.4); }
        .site-input:focus { border-bottom-color: #2B6FDE; }
        /* Real CSS for two-column layouts — arbitrary Tailwind bracket
           classes (e.g. grid-cols-[1fr_2fr]) don't work here because there's
           no JIT compiler, only the prebuilt utility stylesheet. */
        .process-grid {
          display: grid;
          grid-template-columns: 1fr;
        }
        @media (min-width: 1024px) {
          .process-grid {
            grid-template-columns: minmax(0, 0.8fr) minmax(0, 1fr);
            gap: 4rem;
          }
          .process-grid-aside {
            position: sticky;
            top: 110px;
            align-self: start;
          }
        }
        /* Project page sections: a single centred column. The width cap keeps
           body copy at a readable line length on wide screens. */
        .section-column {
          width: 100%;
          max-width: 46rem;
          margin-left: auto;
          margin-right: auto;
        }
        .card-thumb {
          width: 100%;
          aspect-ratio: 4 / 3;
          overflow: hidden;
          position: relative;
        }
        .project-hero {
          width: 100%;
          height: 46vh;
        }
        @media (min-width: 768px) {
          .project-hero { height: 62vh; }
        }
        .next-project-row { transition: background-color 0.15s ease; }
        .next-project-row:hover { background-color: rgba(17,19,24,0.02); }
        /* Advantages: horizontal card track. On large screens the track is
           moved by JS as the pinned section scrolls; below that it's a normal
           swipeable, snapping scroll area. */
        .adv-track {
          display: flex;
          gap: 1.5rem;
          align-items: stretch;
        }
        .adv-card {
          flex: 0 0 auto;
          width: 82vw;
          max-width: 420px;
          scroll-snap-align: start;
          position: relative;
        }
        /* Hairline between cards, sat in the middle of the flex gap rather
           than on a card edge, so the spacing either side of it is even. */
        .adv-card + .adv-card::before {
          content: "";
          position: absolute;
          left: -0.75rem;
          top: 0;
          bottom: 0;
          width: 1px;
          background: ${BORDER};
        }
        .adv-scroll {
          overflow-x: auto;
          scroll-snap-type: x mandatory;
          -webkit-overflow-scrolling: touch;
          scrollbar-width: none;
        }
        .adv-scroll::-webkit-scrollbar { display: none; }
        @media (min-width: 1024px) {
          .adv-track { gap: 2rem; }
          /* Three even columns that exactly fill the container, so the run
             ends with all cards visible and flush to both container edges. */
          .adv-card { width: calc((100% - 4rem) / 3); max-width: none; }
          .adv-card + .adv-card::before { left: -1rem; }
        }
        @media (prefers-reduced-motion: reduce) {
          body { scroll-behavior: auto; }
          * { transition: none !important; animation: none !important; }
        }
      `}</style>
      {loading && <LoadingScreen onDone={finishLoading} />}
      <div className="page-shell" style={{ fontFamily: "'Zalando Sans', sans-serif" }}>
        {route.view === "home" ? (
          <Home
            onOpenProject={openProject}
            onOpenWorkArchive={goToWorkArchive}
            activeTags={activeTags}
            setActiveTags={setActiveTags}
            toggleTag={toggleTag}
            onCta={scrollToContact}
            heroReady={!loading}
          />
        ) : route.view === "privacy" ? (
          <>
            <div className="case-nav">
              <SiteNav onLogoClick={goHome} onWorkClick={goToWorkArchive} onCta={scrollToContact} />
            </div>
            <PrivacyPolicy onBack={goHome} />
          </>
        ) : route.view === "workArchive" ? (
          <>
            <div className="case-nav">
              <SiteNav onLogoClick={goHome} onWorkClick={goToWorkArchive} onCta={scrollToContact} />
            </div>
            <WorkArchive onOpenProject={openProject} activeTags={activeTags} setActiveTags={setActiveTags} toggleTag={toggleTag} />
          </>
        ) : (
          <>
            <div className="case-nav">
              <SiteNav onLogoClick={goHome} onWorkClick={goToWorkArchive} onCta={scrollToContact} />
            </div>
            <ProjectPage project={currentProject} onBack={goHome} onOpenProject={openProject} />
          </>
        )}
        <SiteFooter onPrivacyClick={goToPrivacy} />
      </div>
    </div>
  );
}
